/* Combined former z-prefixed sheets.
   Loaded last by layouts/partials/css.html so these rules still win over
   page CSS. Keep this file last in the cascade; do not rename it to sort
   earlier than privacy/sponsor/webapps sheets unless css.html still appends it.
*/

/* ===== z-contribute-page.css ===== */
/* Contribute — layout aligned with /openms-lib/ (section rhythm, toolkit, resource cards) */

.contribute-page-layout {
  --olib-bg-soft: #f4f6f9;
  --olib-text-muted: var(--openms-text-muted);
  --contribute-max: var(--pro-max, 75rem);
  --contribute-pad: var(--pro-pad);
  --contribute-section-y: var(--pro-section-y, clamp(4rem, 9vw, 6.5rem));
  --contribute-card-radius: 1rem;

  display: block;
  width: 100%;
  max-width: none;
  margin: 0;
  padding: 0;
  background: var(--openms-white);
  color: var(--openms-navy);
}

.contribute-page-layout__body {
  display: block;
}

/* ── Hero (match /openms-lib/ pro hero) ── */
.contribute-page-layout .openms-lib-hero.contribute-page-hero {
  margin: 0;
  padding:
    var(--contribute-section-y)
    var(--openms-page-inline)
    calc(var(--openms-btn-glow-size, 6px) + 0.5rem);
  background: var(--openms-white);
  overflow: visible;
}

.contribute-page-layout .openms-lib-hero.contribute-page-hero::before,
.contribute-page-layout .openms-lib-hero.contribute-page-hero::after,
.contribute-page-layout .openms-lib-hero.contribute-page-hero .openms-lib-hero__panel::after {
  display: none;
}

.contribute-page-layout .openms-lib-hero.contribute-page-hero .openms-lib-hero__panel,
.contribute-page-layout .openms-lib-hero.contribute-page-hero .openms-lib-hero__content {
  text-align: center;
}

.contribute-page-layout .openms-lib-hero.contribute-page-hero .openms-lib-hero__content {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0;
  width: 100%;
  max-width: min(100%, 62rem);
  min-height: 0;
  margin-inline: auto;
}

.contribute-page-layout .openms-lib-hero.contribute-page-hero .openms-lib-hero__eyebrow {
  margin: 0 auto 0.4rem;
}

.contribute-page-layout .openms-lib-hero.contribute-page-hero .openms-lib-hero__title {
  max-width: 26ch;
  width: min(100%, 26ch);
  margin: 0 auto;
  font-family: var(--openms-font-heading);
  font-size: var(--openms-page-hero-title-size, calc(var(--openms-heading-xl-size) * 1.25));
  font-weight: var(--openms-page-hero-title-weight, var(--openms-heading-xl-weight));
  line-height: 1.25;
  letter-spacing: normal;
  text-align: center;
  text-transform: uppercase;
  color: var(--openms-page-hero-title-color, var(--openms-navy));
  text-wrap: balance;
}

.contribute-page-layout .openms-lib-hero.contribute-page-hero .openms-lib-hero__accent,
.contribute-page-layout .openms-lib-hero.contribute-page-hero .openms-lib-hero__accent--warm {
  color: var(--openms-page-hero-title-color, var(--openms-navy));
  -webkit-text-fill-color: var(--openms-page-hero-title-color, var(--openms-navy));
  background: none;
}

.contribute-page-layout .openms-lib-hero.contribute-page-hero .openms-lib-hero__lead {
  max-width: 58ch;
  width: min(100%, 58ch);
  margin: 0.55rem auto 0;
  font-size: clamp(1.02rem, 0.9rem + 0.45vw, 1.2rem);
  line-height: 1.55;
  text-align: center;
  color: var(--openms-text-muted);
}

.contribute-page-layout .openms-lib-hero.contribute-page-hero .openms-lib-hero__actions {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  align-items: center;
  gap: 0.75rem;
  margin-top: 1rem;
  max-width: none;
  width: 100%;
}

.contribute-page-layout .openms-lib-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.35rem;
  flex: 0 1 auto;
  width: auto;
  min-width: 0;
  min-height: 2.75rem;
  padding: var(--openms-btn-padding, 0.7rem 1.25rem);
  border-radius: var(--openms-btn-pill-radius);
  font-family: var(--openms-font-body);
  font-size: var(--openms-text-min);
  font-weight: 600;
  line-height: 1.3;
  white-space: nowrap;
  text-decoration: none !important;
  box-shadow: 0 0 0 0 var(--openms-btn-glow);
  transition: var(--openms-btn-motion);
}

.contribute-page-layout .openms-lib-btn--primary {
  border: 2px solid var(--openms-blue);
  background: var(--openms-blue);
  color: var(--openms-white) !important;
}

.contribute-page-layout .openms-lib-btn--primary::after {
  display: none;
}

.contribute-page-layout .openms-lib-btn--ghost {
  border: 2px solid var(--openms-blue);
  background: transparent;
  color: var(--openms-blue) !important;
}

.contribute-page-layout .openms-lib-btn--primary:hover,
.contribute-page-layout .openms-lib-btn--primary:focus-visible,
.contribute-page-layout .openms-lib-btn--primary:active {
  background: var(--openms-blue);
  border-color: var(--openms-blue);
  color: var(--openms-white) !important;
  transform: scale(var(--openms-btn-hover-scale));
  box-shadow: 0 0 0 var(--openms-btn-glow-size) var(--openms-btn-glow);
  outline: none;
  text-decoration: none !important;
}

.contribute-page-layout .openms-lib-btn--ghost:hover,
.contribute-page-layout .openms-lib-btn--ghost:focus-visible,
.contribute-page-layout .openms-lib-btn--ghost:active {
  background: transparent;
  border-color: var(--openms-blue);
  color: var(--openms-blue) !important;
  transform: scale(var(--openms-btn-hover-scale));
  box-shadow: 0 0 0 var(--openms-btn-glow-size) var(--openms-btn-glow);
  outline: none;
  text-decoration: none !important;
}

.contribute-page-layout .openms-lib-btn .fab,
.contribute-page-layout .openms-lib-btn .fas {
  font-size: 1.05em;
}

/* ── Shared section eyebrow ── */
.contribute-page-layout .contribute-eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  margin: 0 0 0.75rem;
  padding: 0.35rem 0.75rem;
  border: 1px solid rgba(var(--openms-blue-rgb), 0.18);
  border-radius: 999px;
  background: rgba(var(--openms-blue-rgb), 0.1);
  font-size: clamp(0.68rem, 0.52rem + 0.65vw, 0.78rem);
  font-weight: 600;
  letter-spacing: 0.04em;
  text-transform: none;
  color: var(--openms-blue);
  box-shadow: none;
}

.contribute-page-layout .contribute-eyebrow--inverse {
  border-color: rgba(255, 255, 255, 0.22);
  background: rgba(255, 255, 255, 0.1);
  color: rgba(var(--openms-white-rgb), 0.92);
}

/* ── Channels (soft band, like openms-lib about) ── */
.contribute-channels {
  padding:
    var(--contribute-section-y)
    var(--openms-page-inline);
  background: color-mix(in srgb, var(--olib-bg-soft) 45%, var(--openms-white));
}

.contribute-channels__inner {
  max-width: var(--contribute-max);
  margin-inline: auto;
}

.contribute-channels__head,
.contribute-ways__head {
  max-width: 40rem;
  margin: 0 auto clamp(2rem, 4vw, 3rem);
  text-align: center;
}

.contribute-channels__title,
.contribute-ways__title {
  margin: 0;
  font-family: var(--openms-font-heading);
  font-size: clamp(1.85rem, 1rem + 3vw, 2.75rem);
  font-weight: 800;
  line-height: 1.08;
  letter-spacing: -0.03em;
  color: var(--openms-navy);
}

.contribute-channels__lead,
.contribute-ways__lead {
  margin: 0.75rem auto 0;
  max-width: 46ch;
  font-family: var(--openms-font-body);
  font-size: var(--openms-body-size-lg);
  line-height: 1.65;
  color: var(--openms-text-muted) !important;
}

.contribute-channels__grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0.85rem;
}

.contribute-channel {
  display: flex;
  flex-direction: column;
  gap: 0.55rem;
  min-height: 100%;
  padding: clamp(1.25rem, 2.5vw, 1.65rem);
  border: 1px solid rgba(var(--openms-navy-rgb), 0.08);
  border-radius: 1.15rem;
  background: var(--openms-white);
  box-shadow: 0 0.3rem 1rem rgba(var(--openms-navy-rgb), 0.03);
}

.contribute-channel__top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.55rem;
  margin-bottom: 0.15rem;
}

.contribute-channel__icon {
  display: grid;
  place-items: center;
  width: var(--openms-card-icon-chip, 2rem);
  height: var(--openms-card-icon-chip, 2rem);
  border-radius: 0.6rem;
  font-size: var(--openms-card-icon-glyph, 0.85rem);
  color: var(--openms-navy);
  background: rgba(var(--openms-navy-rgb), 0.06);
  box-shadow: inset 0 0 0 1px rgba(var(--openms-navy-rgb), 0.1);
}

.contribute-channel__icon--discord {
  color: var(--openms-blue);
  background: rgba(var(--openms-blue-rgb), 0.1);
  box-shadow: inset 0 0 0 1px rgba(var(--openms-blue-rgb), 0.16);
}

.contribute-channel__tag {
  font-size: 0.66rem;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: rgba(var(--openms-navy-rgb), 0.48);
}

.contribute-channel__title {
  margin: 0;
  font-family: var(--openms-font-heading);
  font-size: clamp(1.15rem, 1rem + 0.5vw, 1.35rem);
  font-weight: 700;
  line-height: 1.25;
  letter-spacing: -0.02em;
  color: var(--openms-navy);
}

.contribute-channel__text {
  margin: 0;
  font-size: var(--openms-body-size);
  line-height: 1.55;
  color: rgba(var(--openms-navy-rgb), 0.64);
}

.contribute-channel__list {
  margin: 0.15rem 0 0;
  padding: 0;
  list-style: none;
  display: grid;
  gap: 0.4rem;
  flex: 1 1 auto;
}

.contribute-channel__list li {
  position: relative;
  margin: 0;
  padding-left: 1.1rem;
  font-size: var(--openms-body-size);
  line-height: 1.45;
  color: var(--openms-text-muted);
}

.contribute-channel__list li::before {
  content: "";
  position: absolute;
  left: 0;
  top: 0.55em;
  width: 0.35rem;
  height: 0.35rem;
  border-radius: 50%;
  background: var(--openms-blue);
}

.contribute-channel__link,
.contribute-way__link {
  display: inline-flex;
  align-items: center;
  align-self: flex-start;
  gap: 0.3rem;
  margin-top: auto;
  padding-top: 0.55rem;
  font-size: var(--openms-text-min);
  font-weight: var(--openms-cta-link-weight, 700);
  line-height: 1.4;
  color: var(--openms-cta-link, var(--openms-navy));
  text-decoration: none !important;
  transition: gap 0.2s ease, color 0.2s ease;
}

.contribute-channel__link {
  color: var(--openms-cta-link, var(--openms-navy)) !important;
}

.contribute-channel:hover .contribute-channel__link,
.contribute-channel:focus-within .contribute-channel__link,
.contribute-channel__link:hover,
.contribute-channel__link:focus-visible {
  gap: 0.5rem;
  color: var(--openms-cta-link-hover, var(--openms-blue)) !important;
  outline: none;
}

/* ── Ways (toolkit + polished contribution cards) ── */
.contribute-ways {
  padding:
    var(--contribute-section-y)
    var(--openms-page-inline);
  background: color-mix(in srgb, var(--olib-bg-soft) 55%, var(--openms-white));
}

.contribute-ways__inner {
  max-width: var(--contribute-max);
  margin-inline: auto;
}

.contribute-ways__toolkit {
  display: grid;
  grid-template-columns: minmax(0, 0.95fr) minmax(0, 1.25fr);
  gap: 1rem;
  align-items: stretch;
}

.contribute-ways__feature {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: 0.85rem;
  min-height: 100%;
  overflow: hidden;
  padding: clamp(1.5rem, 3vw, 2.1rem);
  border: 1px solid rgba(var(--openms-blue-rgb), 0.18);
  border-radius: 1.35rem;
  background:
    radial-gradient(
      120% 90% at 100% 0%,
      rgba(var(--openms-blue-rgb), 0.14) 0%,
      rgba(var(--openms-blue-rgb), 0) 55%
    ),
    linear-gradient(
      165deg,
      var(--openms-white) 0%,
      color-mix(in srgb, var(--openms-blue) 5%, var(--openms-white)) 100%
    );
  color: var(--openms-navy);
  box-shadow:
    0 1px 2px rgba(var(--openms-navy-rgb), 0.04),
    0 14px 32px -18px rgba(var(--openms-navy-rgb), 0.22);
}

.contribute-ways__feature-kicker {
  display: inline-flex;
  align-items: center;
  gap: 0.55rem;
  margin: 0;
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: rgba(var(--openms-navy-rgb), 0.58);
}

.contribute-ways__feature-icon {
  display: grid;
  place-items: center;
  width: 2.35rem;
  height: 2.35rem;
  border-radius: 0.8rem;
  font-size: 1rem;
  color: var(--openms-white);
  background: linear-gradient(
    135deg,
    var(--openms-blue) 0%,
    color-mix(in srgb, var(--openms-blue) 55%, var(--openms-navy)) 100%
  );
  box-shadow: 0 8px 16px -8px rgba(var(--openms-blue-rgb), 0.55);
}

.contribute-ways__feature-title {
  margin: 0;
  font-family: var(--openms-font-heading);
  font-size: clamp(1.5rem, 1.05rem + 1.4vw, 2rem);
  font-weight: 800;
  line-height: 1.12;
  letter-spacing: -0.03em;
  color: var(--openms-navy);
}

.contribute-ways__feature-text {
  margin: 0;
  max-width: 36ch;
  font-size: var(--openms-body-size);
  line-height: 1.65;
  color: rgba(var(--openms-navy-rgb), 0.66);
}

.contribute-project-links {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0.65rem;
  margin: auto 0 0;
  padding: 0.5rem 0 0;
  list-style: none;
}

.contribute-project-links li {
  margin: 0;
}

.contribute-project-link {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 0.45rem;
  width: 100%;
  box-sizing: border-box;
  padding: 0.7rem 0.55rem 0.65rem;
  border: 1px solid rgba(var(--openms-white-rgb), 0.22);
  border-radius: 0.85rem;
  background: rgba(var(--openms-white-rgb), 0.08);
  font-family: var(--openms-font-body);
  font-size: var(--openms-text-min);
  font-weight: 700;
  color: var(--openms-white) !important;
  text-decoration: none !important;
  text-align: center;
  line-height: 1.25;
  transition: border-color 0.2s ease, background 0.2s ease, transform 0.2s ease;
}

.contribute-project-link__icon {
  display: grid;
  place-items: center;
  width: 100%;
  max-width: 7.5rem;
  height: 2.75rem;
}

.contribute-project-link__icon img {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: contain;
}

.contribute-project-link:hover,
.contribute-project-link:focus-visible {
  border-color: rgba(var(--openms-white-rgb), 0.5);
  background: rgba(var(--openms-white-rgb), 0.14);
  color: var(--openms-white) !important;
  transform: translateY(-2px);
  outline: none;
}

.contribute-ways__grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 1rem;
}

.contribute-ways__more {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 1rem;
  margin-top: 1rem;
}

.contribute-way {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: 0.55rem;
  min-height: 100%;
  padding: clamp(1.2rem, 2.4vw, 1.5rem);
  border: 1px solid rgba(var(--openms-navy-rgb), 0.08);
  border-radius: 1.25rem;
  background: linear-gradient(
    180deg,
    var(--openms-white) 0%,
    color-mix(in srgb, var(--openms-blue) 4%, var(--openms-white)) 100%
  );
  box-shadow:
    0 1px 2px rgba(var(--openms-navy-rgb), 0.04),
    0 10px 24px -14px rgba(var(--openms-navy-rgb), 0.18);
  transition: transform 0.25s ease, box-shadow 0.25s ease, border-color 0.25s ease;
}

.contribute-way:hover,
.contribute-way:focus-within {
  transform: translateY(-3px);
  border-color: rgba(var(--openms-blue-rgb), 0.22);
  box-shadow:
    0 1px 2px rgba(var(--openms-navy-rgb), 0.04),
    0 18px 36px -16px rgba(var(--openms-navy-rgb), 0.28);
}

.contribute-way__top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.55rem;
  margin-bottom: 0.1rem;
}

.contribute-way__icon {
  display: grid;
  place-items: center;
  width: 2.6rem;
  height: 2.6rem;
  border-radius: 0.85rem;
  font-size: 1.05rem;
  color: var(--openms-white);
  background: linear-gradient(
    135deg,
    var(--openms-blue) 0%,
    color-mix(in srgb, var(--openms-blue) 55%, var(--openms-navy)) 100%
  );
  box-shadow: 0 8px 16px -8px rgba(var(--openms-blue-rgb), 0.55);
  transition: transform 0.25s ease;
}

.contribute-way:hover .contribute-way__icon,
.contribute-way:focus-within .contribute-way__icon {
  transform: scale(1.05);
}

.contribute-way__tag {
  font-size: 0.66rem;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: rgba(var(--openms-navy-rgb), 0.48);
}

.contribute-way__title {
  margin: 0;
  font-family: var(--openms-font-heading);
  font-size: clamp(1.05rem, 0.92rem + 0.45vw, 1.18rem);
  font-weight: 700;
  line-height: 1.28;
  letter-spacing: -0.02em;
  color: var(--openms-navy);
}

.contribute-way__text {
  margin: 0;
  flex: 1 1 auto;
  font-size: var(--openms-body-size);
  line-height: 1.55;
  color: rgba(var(--openms-navy-rgb), 0.64);
}

.contribute-way__text a {
  color: var(--openms-content-link, var(--openms-navy));
  font-weight: var(--openms-content-link-weight, 600);
  text-decoration: none;
  text-underline-offset: var(--openms-content-link-underline-offset, 0.12em);
}

.contribute-way__text a:hover,
.contribute-way__text a:focus-visible {
  color: var(--openms-content-link-hover, var(--openms-blue));
  text-decoration: none;
}

.contribute-way__meta {
  display: flex;
  align-items: center;
  min-height: 1.4rem;
  margin: 0;
}

.contribute-way__meta img {
  display: block;
  height: 1.25rem;
  width: auto;
}

.contribute-way__badge {
  display: inline-flex;
  align-self: flex-start;
  margin: 0.1rem 0 0;
  line-height: 0;
  text-decoration: none;
}

.contribute-way__badge img {
  display: block;
  height: 1.35rem;
  width: auto;
}

.contribute-way__badge:hover,
.contribute-way__badge:focus-visible {
  opacity: 0.88;
  outline: none;
}

.contribute-way__actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.5rem;
  margin-top: auto;
  padding-top: 0.55rem;
}

.contribute-way__actions .openms-lib-btn {
  flex: 1 1 auto;
  min-width: 0;
  min-height: var(--openms-btn-min-height, 2.75rem);
  padding: var(--openms-btn-padding);
  font-size: var(--openms-btn-font-size, var(--openms-text-min));
}

.contribute-way__actions .openms-lib-btn--ghost {
  border: 2px solid rgba(var(--openms-navy-rgb), 0.22);
  background: transparent;
  color: var(--openms-navy) !important;
}

.contribute-way__actions .openms-lib-btn--ghost:hover,
.contribute-way__actions .openms-lib-btn--ghost:focus-visible,
.contribute-way__actions .openms-lib-btn--ghost:active {
  border-color: var(--openms-navy);
  background: transparent;
  color: var(--openms-navy) !important;
  transform: scale(var(--openms-btn-hover-scale));
  box-shadow: 0 0 0 var(--openms-btn-glow-size) rgba(var(--openms-navy-rgb), 0.12);
  outline: none;
}

.contribute-os-buttons {
  display: flex;
  flex-wrap: wrap;
  gap: var(--openms-btn-gap, 0.75rem);
  margin-top: 0.1rem;
}

.contribute-os-btn {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  min-height: 2rem;
  padding: 0.28rem 0.7rem;
  border: 1px solid rgba(var(--openms-blue-rgb), 0.2);
  border-radius: 999px;
  background: rgba(var(--openms-blue-rgb), 0.05);
  font-size: 0.78rem;
  font-weight: 700;
  color: var(--openms-blue) !important;
  text-decoration: none !important;
  transition: border-color 0.2s ease, background 0.2s ease, color 0.2s ease;
}

.contribute-os-btn:hover,
.contribute-os-btn:focus-visible {
  border-color: var(--openms-blue);
  background: rgba(var(--openms-blue-rgb), 0.1);
  color: var(--openms-blue) !important;
  text-decoration: none !important;
  outline: none;
}

.contribute-way__link {
  display: inline-flex;
  align-items: center;
  align-self: flex-start;
  gap: 0.3rem;
  margin-top: auto;
  padding-top: 0.55rem;
  font-size: var(--openms-text-min);
  font-weight: var(--openms-cta-link-weight, 700);
  line-height: 1.4;
  color: var(--openms-cta-link, var(--openms-navy)) !important;
  text-decoration: none !important;
  transition: gap 0.2s ease, color 0.2s ease;
}

.contribute-way:hover .contribute-way__link,
.contribute-way:focus-within .contribute-way__link,
.contribute-way__link:hover,
.contribute-way__link:focus-visible {
  gap: 0.5rem;
  color: var(--openms-cta-link-hover, var(--openms-blue)) !important;
  outline: none;
}

/* ── Code of Conduct (full-bleed CTA band like openms-lib) ── */
.contribute-conduct {
  padding:
    clamp(2.5rem, 5vw, 3.5rem)
    var(--openms-page-inline);
  background: var(--openms-navy);
}

.contribute-conduct__inner {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0;
  max-width: var(--contribute-max);
  margin-inline: auto;
  text-align: center;
}

.contribute-conduct__copy {
  max-width: 40rem;
  margin: 0 auto;
}

.contribute-conduct__title {
  margin: 0;
  font-family: var(--openms-font-heading);
  font-size: clamp(1.85rem, 1rem + 3vw, 2.75rem);
  font-weight: 800;
  line-height: 1.08;
  letter-spacing: -0.03em;
  color: var(--openms-white);
}

.contribute-conduct__lead {
  margin: 0.75rem auto 0;
  max-width: 46ch;
  font-size: var(--openms-body-size-lg);
  line-height: 1.65;
  color: rgba(255, 255, 255, 0.72);
}

.contribute-conduct__actions {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 0.75rem;
  margin-top: 1.75rem;
}

.contribute-page-layout .contribute-conduct__btn {
  border: 2px solid rgba(255, 255, 255, 0.45) !important;
  background: transparent !important;
  color: var(--openms-white) !important;
}

.contribute-page-layout .contribute-conduct__btn:hover,
.contribute-page-layout .contribute-conduct__btn:focus-visible,
.contribute-page-layout .contribute-conduct__btn:active {
  border-color: var(--openms-white) !important;
  background: rgba(255, 255, 255, 0.1) !important;
  color: var(--openms-white) !important;
  transform: scale(var(--openms-btn-hover-scale));
  box-shadow: 0 0 0 var(--openms-btn-glow-size) rgba(255, 255, 255, 0.16);
  outline: none;
}

/* ── Responsive ── */
@media (max-width: 960px) {
  .contribute-ways__toolkit {
    grid-template-columns: 1fr;
  }

  .contribute-ways__more {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 900px) {
  .contribute-page-layout .openms-lib-hero.contribute-page-hero .openms-lib-hero__title {
    font-size: calc(var(--openms-heading-xl-size) * 1.18);
  }
}

@media (max-width: 720px) {
  .contribute-channels__grid,
  .contribute-ways__grid,
  .contribute-ways__more {
    grid-template-columns: 1fr;
  }

  .contribute-project-links {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 640px) {
  .contribute-page-layout .openms-lib-hero.contribute-page-hero .openms-lib-hero__actions {
    flex-direction: row;
    flex-wrap: wrap;
    gap: 0.65rem;
  }

  .contribute-page-layout .openms-lib-hero.contribute-page-hero .openms-lib-hero__actions .openms-lib-btn {
    flex: 1 1 auto;
    min-width: min(100%, 11rem);
    white-space: nowrap;
    font-size: var(--openms-btn-font-size, var(--openms-text-min));
    min-height: var(--openms-btn-min-height, 2.75rem);
    padding: var(--openms-btn-padding);
  }
}

@media (max-width: 480px) {
  .contribute-page-layout .openms-lib-hero.contribute-page-hero .openms-lib-hero__title {
    font-size: calc(var(--openms-heading-xl-size) * 1.05);
    line-height: 1.2;
    letter-spacing: normal;
  }

  .contribute-page-layout .openms-lib-hero.contribute-page-hero .openms-lib-hero__lead {
    font-size: clamp(0.9rem, 3.8vw, 1rem);
    line-height: 1.5;
  }
}

@media (prefers-reduced-motion: reduce) {
  .contribute-page-layout .openms-lib-btn:hover,
  .contribute-page-layout .openms-lib-btn:focus-visible,
  .contribute-project-link:hover,
  .contribute-project-link:focus-visible,
  .contribute-way:hover,
  .contribute-way:focus-within,
  .contribute-way__actions .openms-lib-btn:hover,
  .contribute-way__actions .openms-lib-btn:focus-visible {
