}

.openms-lib-page--hub.openms-lib-page--webapps .openms-lib-hero__lead {
  max-width: min(68ch, 94vw);
}

.openms-lib-page--hub .openms-lib-hero__actions {
  display: inline-flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: center;
  gap: clamp(0.55rem, 2vw, 0.75rem);
