/* Developer retreat — reuse openms-lib pro shell */
.openms-lib-page--developer-retreat #upcoming-retreat {
  background: var(--pro-band-soft);
}

.openms-lib-page--developer-retreat #about-the-retreat {
  background: var(--openms-white);
}

.openms-lib-page--developer-retreat #about-the-retreat .openms-lib-about__head {
  display: grid;
  grid-template-columns: 1fr;
  gap: 0;
  align-items: start;
  max-width: min(100%, 42rem);
  margin: 0 0 var(--pro-head-to-content);
  text-align: left;
}

.openms-lib-page--developer-retreat #about-the-retreat .openms-lib-about__head-copy {
  display: grid;
  gap: 0;
  justify-items: start;
  width: 100%;
  max-width: 100%;
}

.openms-lib-page--developer-retreat #about-the-retreat .openms-lib-about__eyebrow,
.openms-lib-page--developer-retreat #about-the-retreat .openms-lib-about__title {
  margin: 0;
}

.openms-lib-page--developer-retreat #past-retreat {
  background: var(--pro-band-soft);
  padding-block: var(--pro-section-y);
  padding-top: calc(var(--pro-section-y) * 0.45);
}

.openms-lib-page--developer-retreat .retreat-upcoming {
  padding-block: var(--pro-section-y);
}

.openms-lib-page--developer-retreat .retreat-upcoming__inner {
  display: grid;
  grid-template-columns: minmax(0, 0.95fr) minmax(0, 1.05fr);
  gap: var(--pro-col-gap);
  align-items: center;
}

.openms-lib-page--developer-retreat .retreat-upcoming__head {
  grid-template-columns: 1fr;
  align-items: start;
  margin: 0;
}

.openms-lib-page--developer-retreat .retreat-upcoming__facts,
.openms-lib-page--developer-retreat .retreat-upcoming__list {
  display: grid;
  gap: 0.65rem;
  margin: 1rem 0 0;
  padding: 0;
  list-style: none;
}

.openms-lib-page--developer-retreat .retreat-upcoming__facts li {
  display: flex;
  align-items: flex-start;
  gap: 0.65rem;
  margin: 0;
  font-size: var(--openms-body-size-lg);
  line-height: 1.45;
  color: rgba(var(--openms-dark-rgb), 0.82);
}

.openms-lib-page--developer-retreat .retreat-upcoming__facts i {
  display: grid;
  place-items: center;
  flex: 0 0 1.5rem;
  width: 1.5rem;
  margin-top: 0.15em;
  color: var(--openms-navy);
}

.openms-lib-page--developer-retreat .retreat-upcoming__list li {
  position: relative;
  margin: 0;
  padding-left: 1rem;
  font-size: var(--openms-body-size-lg);
  line-height: 1.5;
  color: rgba(var(--openms-dark-rgb), 0.82);
}

.openms-lib-page--developer-retreat .retreat-upcoming__list li::before {
  content: "";
  position: absolute;
  left: 0;
  top: 0.6em;
  width: 0.32rem;
  height: 0.32rem;
  border-radius: 50%;
  background: rgba(var(--openms-navy-rgb), 0.4);
}

.openms-lib-page--developer-retreat .retreat-upcoming__actions {
  margin-top: 1.35rem;
}

.openms-lib-page--developer-retreat .retreat-upcoming__sponsor {
  margin: 1rem 0 0;
  font-size: var(--openms-body-size);
  line-height: 1.5;
  color: var(--pro-text-muted);
}

.openms-lib-page--developer-retreat .retreat-upcoming__sponsor a {
  color: var(--openms-navy);
  font-weight: 600;
  text-decoration: underline;
  text-underline-offset: 0.14em;
}

.openms-lib-page--developer-retreat .retreat-upcoming__poster {
  margin: 0;
}

.openms-lib-page--developer-retreat .retreat-upcoming__poster img {
  display: block;
  width: 100%;
  height: auto;
  border-radius: var(--pro-radius);
  box-shadow: var(--pro-shadow);
}

.openms-lib-page--developer-retreat .retreat-highlights__mosaic {
