.openms-lib-page--code-of-conduct .coc-principle__text {
  margin: 0;
  font-size: var(--openms-body-size);
  line-height: 1.5;
  color: rgba(var(--openms-navy-rgb), 0.68);
}

/* —— Report callout —— */
.openms-lib-page--code-of-conduct .coc-report {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: center;
  gap: 1rem 1.75rem;
  width: 100%;
  margin: 0;
  padding: clamp(1.15rem, 2.5vw, 1.45rem) clamp(1.2rem, 2.8vw, 1.6rem);
  border: none;
  border-radius: var(--pro-radius, 0.85rem);
  background: var(--openms-white);
  box-shadow: var(--pro-shadow, 0 0.15rem 0.65rem rgba(var(--openms-navy-rgb), 0.04));
}

.openms-lib-page--code-of-conduct .coc-report__copy {
  display: grid;
  gap: 0.4rem;
  min-width: 0;
}

.openms-lib-page--code-of-conduct .coc-report__kicker {
  margin: 0;
  font-size: var(--openms-text-min);
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--pro-eyebrow, rgba(var(--openms-blue-rgb), 0.72));
}

.openms-lib-page--code-of-conduct .coc-report__text {
  margin: 0;
  font-size: var(--openms-body-size);
  line-height: 1.55;
  color: rgba(var(--openms-dark-rgb), 0.78);
}

.openms-lib-page--code-of-conduct .coc-report__text a {
  color: var(--openms-blue);
  font-weight: var(--openms-content-link-weight, 600);
  text-decoration: none;
  text-underline-offset: var(--openms-content-link-underline-offset, 0.12em);
  overflow-wrap: anywhere;
}

.openms-lib-page--code-of-conduct .coc-details__answer a {
  color: var(--openms-content-link, var(--openms-navy));
  font-weight: var(--openms-content-link-weight, 600);
  text-decoration: none;
  text-underline-offset: var(--openms-content-link-underline-offset, 0.12em);
  overflow-wrap: anywhere;
}

.openms-lib-page--code-of-conduct .coc-report__text a:hover,
.openms-lib-page--code-of-conduct .coc-report__text a:focus-visible {
  color: var(--openms-blue);
  text-decoration: none;
}

.openms-lib-page--code-of-conduct .coc-details__answer a:hover,
.openms-lib-page--code-of-conduct .coc-details__answer a:focus-visible {
  color: var(--openms-content-link-hover, var(--openms-blue));
  text-decoration: none;
}

.openms-lib-page--code-of-conduct .coc-report__link {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  flex-shrink: 0;
  font-size: var(--openms-text-min);
  font-weight: var(--openms-cta-link-weight, 700);
  line-height: 1.35;
  color: var(--openms-blue);
  text-decoration: none;
  white-space: nowrap;
}

.openms-lib-page--code-of-conduct .coc-report__link:hover,
.openms-lib-page--code-of-conduct .coc-report__link:focus-visible {
  color: var(--openms-blue);
  outline: none;
}

/* —— Full policy dropdowns —— */
.openms-lib-page--code-of-conduct .coc-details {
  padding-bottom: 0;
}

.openms-lib-page--code-of-conduct .coc-details__head {
  display: grid;
  grid-template-columns: 1fr;
  gap: 0;
  align-items: start;
  margin-bottom: 0;
}

.openms-lib-page--code-of-conduct .coc-details__head-copy {
  display: grid;
  justify-items: start;
  text-align: left;
  max-width: min(100%, 42rem);
}

.openms-lib-page--code-of-conduct .coc-details__body {
  display: grid;
  gap: 0.85rem;
  width: 100%;
}

.openms-lib-page--code-of-conduct .coc-details__toolbar {
  display: flex;
  flex-wrap: wrap;
  gap: 0.55rem;
  justify-content: flex-end;
  width: 100%;
  margin: 0;
}

.openms-lib-page--code-of-conduct .coc-details__tool-btn {
  appearance: none;
  margin: 0;
  min-height: 2.5rem;
  padding: 0.45rem 0.95rem;
  border: 1px solid var(--pro-line, rgba(var(--openms-navy-rgb), 0.12));
  border-radius: 999px;
  background: var(--openms-white);
  color: var(--openms-navy, #0b1f33);
  font: inherit;
  font-size: var(--openms-text-min);
  font-weight: 600;
  cursor: pointer;
}

.openms-lib-page--code-of-conduct .coc-details__tool-btn:hover,
.openms-lib-page--code-of-conduct .coc-details__tool-btn:focus-visible {
  border-color: color-mix(in srgb, var(--openms-blue) 40%, var(--pro-line, rgba(var(--openms-navy-rgb), 0.12)));
  color: var(--openms-blue);
  outline: none;
}

.openms-lib-page--code-of-conduct .coc-details__list {
  display: grid;
  gap: 0.65rem;
  width: 100%;
  max-width: none;
  margin: 0;
}

.openms-lib-page--code-of-conduct .coc-details__item {
  border: 1px solid var(--pro-line, rgba(var(--openms-navy-rgb), 0.12));
  border-radius: var(--pro-radius, 0.85rem);
  background: var(--openms-white);
  box-shadow: none;
  overflow: clip;
  scroll-margin-top: 6rem;
}

.openms-lib-page--code-of-conduct .coc-details__summary {
  display: grid;
  grid-template-columns: auto 1fr auto;
  align-items: start;
  gap: 0.85rem 1rem;
  min-height: 3.5rem;
  padding: 1rem 1.15rem;
  cursor: pointer;
  list-style: none;
}

.openms-lib-page--code-of-conduct .coc-details__summary::-webkit-details-marker {
  display: none;
}

.openms-lib-page--code-of-conduct .coc-details__summary::after {
  content: "";
  width: 0.55rem;
  height: 0.55rem;
  margin-top: 0.45rem;
  border-right: 2px solid var(--openms-navy, #0b1f33);
  border-bottom: 2px solid var(--openms-navy, #0b1f33);
  transform: rotate(45deg);
  transition: transform 0.15s ease;
  justify-self: end;
}

.openms-lib-page--code-of-conduct .coc-details__item[open] .coc-details__summary::after {
  transform: rotate(225deg);
  margin-top: 0.65rem;
}

.openms-lib-page--code-of-conduct .coc-details__index {
  margin-top: 0.2rem;
  font-size: var(--openms-text-min);
  font-weight: 700;
  letter-spacing: 0.06em;
  color: var(--openms-blue);
  font-variant-numeric: tabular-nums;
}

.openms-lib-page--code-of-conduct .coc-details__summary-copy {
  display: grid;
  gap: 0.25rem;
  min-width: 0;
}

.openms-lib-page--code-of-conduct .coc-details__question-title {
  margin: 0;
  font-family: var(--openms-font-heading);
  font-size: clamp(1rem, 1.5vw, 1.12rem);
  font-weight: 700;
  line-height: 1.3;
  color: rgba(var(--openms-dark-rgb), 0.72);
}

.openms-lib-page--code-of-conduct .coc-details__summary-text {
  color: rgba(var(--openms-navy-rgb), 0.58);
  font-size: var(--openms-body-size);
  line-height: 1.45;
}

.openms-lib-page--code-of-conduct .coc-details__answer {
  display: grid;
  gap: 0.85rem;
  padding: 0 1.15rem 1.2rem;
  border-top: 1px solid var(--pro-line, rgba(var(--openms-navy-rgb), 0.12));
}

.openms-lib-page--code-of-conduct .coc-details__answer > *:first-child {
  margin-top: 1rem;
}

.openms-lib-page--code-of-conduct .coc-details__answer p,
.openms-lib-page--code-of-conduct .coc-details__answer li {
  margin: 0;
  font-size: var(--openms-body-size);
  line-height: 1.65;
  color: rgba(var(--openms-dark-rgb), 0.72);
}

.openms-lib-page--code-of-conduct .coc-details__answer ul,
.openms-lib-page--code-of-conduct .coc-details__answer ol {
  margin: 0;
  padding-left: 1.25rem;
  display: grid;
  gap: 0.4rem;
  list-style: disc;
}

.openms-lib-page--code-of-conduct .coc-details__answer ol {
  list-style: decimal;
}

/* —— Quiet attribution footer —— */
.openms-lib-page--code-of-conduct .openms-lib-page__outro {
  background: var(--openms-white);
  padding-inline: 0;
  padding-block: 0;
}

.openms-lib-page--code-of-conduct .openms-lib-page__outro > .openms-lib-page__anchor {
  padding-inline: var(--openms-page-inline);
  padding-block: 0.85rem 2rem;
  box-sizing: border-box;
}

.openms-lib-page--code-of-conduct .coc-attribution {
  width: 100%;
  max-width: min(100%, 48rem);
  margin: 0;
  padding: 0.75rem 0 0;
  border-top: 1px solid rgba(var(--openms-navy-rgb), 0.06);
}

.openms-lib-page--code-of-conduct .coc-attribution__text {
  margin: 0;
  font-size: 0.72rem;
  line-height: 1.45;
  color: rgba(var(--openms-dark-rgb), 0.45);
}

@media (max-width: 1100px) {
  .openms-lib-page--code-of-conduct .coc-overview__principles {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
}

