/* ===== zz-contribute-page.css ===== */
/* Contribute page — layouts use shared pro spacing rhythm */

.openms-lib-page--contribute {
  --contribute-space-1: var(--pro-space-1, 0.5rem);
  --contribute-space-2: var(--pro-space-2, 0.75rem);
  --contribute-space-3: var(--pro-space-3, 1rem);
  --contribute-space-4: var(--pro-space-4, 1.25rem);
  --contribute-space-5: var(--pro-space-5, 1.75rem);
  --contribute-space-6: var(--pro-space-6, clamp(2.25rem, 4.5vw, 3.25rem));
  --contribute-max: var(--pro-max, 75rem);
  --contribute-pad: var(--openms-page-inline, clamp(1.25rem, 4vw, 2.5rem));
  --contribute-section-y: var(--pro-section-y, clamp(4rem, 9vw, 6.5rem));
  --contribute-soft: var(--pro-band-soft, #f4f6f9);
  --contribute-border: var(--pro-line, rgba(var(--openms-navy-rgb), 0.1));
  --contribute-motion: 0.28s cubic-bezier(0.44, 0, 0.56, 1);
  --contribute-gutter: max(
    var(--contribute-pad),
    calc((100% - var(--contribute-max)) / 2)
  );
}

/* Full-bleed shells; anchors keep standard section-y like other hub pages */
.openms-lib-page--contribute.openms-lib-page--openms-lib .openms-lib-page__body > .openms-lib-page__anchor,
.openms-lib-page--contribute .openms-lib-page__body > .openms-lib-page__anchor {
  width: 100%;
  max-width: none;
  padding-inline: 0;
  padding-block: var(--contribute-section-y) 0;
  background: transparent;
}

.openms-lib-page--contribute .openms-lib-page__body > .openms-lib-page__anchor:nth-child(even) {
  background: transparent;
}

/* Ways — soft band edge-to-edge (page-wide) */
.openms-lib-page--contribute #ways-to-contribute.openms-lib-page__anchor {
  width: 100%;
  max-width: none;
  margin-inline: 0;
  padding-inline: 0;
  background: var(--contribute-soft, var(--pro-band-soft, #f4f6f9));
}

.openms-lib-page--contribute .contribute-channels,
.openms-lib-page--contribute .contribute-ways,
.openms-lib-page--contribute .contribute-track,
.openms-lib-page--contribute .contribute-support,
.openms-lib-page--contribute .contribute-outreach {
  width: 100%;
  max-width: none;
  box-sizing: border-box;
  margin-inline: 0;
}

.openms-lib-page--contribute .contribute-channels__strip {
  width: 100%;
  max-width: none;
  margin-inline: 0;
  box-sizing: border-box;
}

/* ── Hero ── */
.openms-lib-page--contribute .openms-lib-hero--pro {
  padding-bottom: calc(var(--openms-btn-glow-size, 6px) + 0.5rem);
  overflow: visible;
}

.openms-lib-page--contribute  {
  gap: 0;
}

.openms-lib-page--contribute .openms-lib-hero__eyebrow {
  margin: 0 auto var(--pro-stack-eyebrow, 0.5rem);
  font-size: var(--openms-text-min) !important;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--pro-eyebrow, rgba(var(--openms-blue-rgb), 0.72));
}

.openms-lib-page--contribute .openms-lib-hero__title {
  max-width: min(20ch, 94vw);
  margin: 0 auto;
  font-size: var(--openms-page-hero-title-size) !important;
  font-weight: var(--openms-page-hero-title-weight, var(--openms-heading-xl-weight, 800));
  line-height: 1.12;
  letter-spacing: -0.02em;
}

.openms-lib-page--contribute .openms-lib-hero__lead {
  max-width: min(42ch, 92vw);
  margin: var(--pro-stack-lead, 1rem) auto 0;
  font-size: var(--openms-body-size-lg) !important;
  line-height: 1.65;
  white-space: normal;
  text-wrap: balance;
  color: var(--pro-text-muted, rgba(var(--openms-navy-rgb), 0.68));
}

.openms-lib-page--contribute .openms-lib-hero__actions {
  margin-top: var(--pro-stack-actions, 2rem);
}

.openms-lib-page--contribute .openms-lib-hero__actions .openms-lib-btn--primary .fab,
.openms-lib-page--contribute .openms-lib-hero__actions .openms-lib-btn--primary .svg-inline--fa {
  color: var(--openms-white) !important;
}

.openms-lib-page--contribute .openms-lib-hero__actions .openms-lib-btn--primary .svg-inline--fa path {
  fill: currentColor !important;
}

.openms-lib-page--contribute .openms-lib-hero__actions .openms-lib-btn--ghost .fab,
.openms-lib-page--contribute .openms-lib-hero__actions .openms-lib-btn--ghost .svg-inline--fa {
  color: var(--openms-blue) !important;
}

.openms-lib-page--contribute .openms-lib-hero__actions .openms-lib-btn--ghost .svg-inline--fa path {
  fill: currentColor !important;
}

.openms-lib-page--contribute .openms-lib-page__body > .openms-lib-page__anchor {
  background: transparent;
}

.openms-lib-page--contribute .openms-lib-page__body {
  margin-top: 0;
}

.openms-lib-page--contribute #communication-channels.openms-lib-page__anchor {
  padding-top: var(--contribute-section-y);
}

/* Shared kickers */
.contribute-channels__eyebrow,
.contribute-ways__eyebrow,
.contribute-support__kicker,
.contribute-outreach__eyebrow {
  margin: 0;
  font-size: var(--openms-text-min);
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--openms-blue);
}

/* ═══════════════════════════════════════════
   1. CHANNELS — numbered 3-up strip
   ═══════════════════════════════════════════ */
.contribute-channels {
  padding: 0 var(--contribute-gutter);
  background: var(--openms-white);
}

.contribute-channels__head {
  width: 100%;
  max-width: 36rem;
  margin: 0 auto var(--pro-head-to-content, var(--contribute-space-6));
  text-align: center;
  display: grid;
  gap: var(--pro-stack-eyebrow, var(--contribute-space-1));
  justify-items: center;
}

.contribute-channels__title {
  margin: 0;
  font-family: var(--openms-font-heading);
  font-size: var(--openms-section-title-size) !important;
  font-weight: var(--openms-heading-lg-weight, 800);
  line-height: 1.15;
  letter-spacing: -0.02em;
  text-transform: uppercase;
  color: var(--openms-navy);
}

.contribute-channels__lead {
  margin: var(--pro-stack-lead, var(--contribute-space-2)) 0 0;
  font-size: var(--openms-body-size-lg);
  line-height: 1.65;
  color: var(--openms-text-muted) !important;
}

.contribute-channels__strip {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 0;
  width: 100%;
  margin-inline: 0;
  border-top: 1px solid var(--contribute-border);
  border-bottom: 1px solid var(--contribute-border);
}

.contribute-channel {
  position: relative;
  display: grid;
  gap: var(--contribute-space-2);
  align-content: start;
  padding: var(--contribute-space-6) var(--contribute-space-4);
  border: none;
  border-right: 1px solid var(--contribute-border);
  background: transparent;
  transition: background-color var(--contribute-motion);
}

.contribute-channel:last-child {
  border-right: none;
}

.contribute-channel:hover,
.contribute-channel:focus-within {
  background: var(--openms-num-strip-hover-bg);
  box-shadow: none;
  transform: none;
}

/* Index typography comes from brand-palette shared step numbers */

.contribute-channel__icon {
  display: none;
}

.contribute-channel__title {
  margin: 0;
  font-family: var(--openms-font-heading);
  font-size: var(--openms-card-title-size) !important;
  font-weight: 700;
  line-height: 1.3;
  color: var(--openms-navy);
}

.contribute-channel__text {
  margin: 0;
  font-size: var(--openms-body-size);
  line-height: 1.6;
  color: rgba(var(--openms-navy-rgb), 0.68);
}

.contribute-channel__link {
  display: inline-flex;
  align-items: center;
  gap: 0.3rem;
  margin-top: var(--contribute-space-1);
  font-size: var(--openms-text-min);
  font-weight: 700;
  color: var(--openms-navy) !important;
  text-decoration: none !important;
  transition: gap var(--contribute-motion), color var(--contribute-motion);
}

.contribute-channel:hover .contribute-channel__link,
.contribute-channel:focus-within .contribute-channel__link {
  gap: 0.5rem;
  color: var(--openms-blue) !important;
}

/* ═══════════════════════════════════════════
   2. WAYS — intro + numbered contribution track
   ═══════════════════════════════════════════ */
.contribute-ways {
  display: grid;
  gap: 0;
  background: transparent;
}

.contribute-ways__head {
  display: grid;
  justify-items: start;
  text-align: left;
  gap: 0;
  width: 100%;
  margin: 0;
  padding: 0 var(--contribute-gutter) var(--pro-head-to-content, var(--contribute-space-6));
  box-sizing: border-box;
  border-bottom: none;
  background: transparent;
}

.contribute-ways__eyebrow {
  margin: 0 0 var(--pro-stack-eyebrow, 0.5rem);
}

.contribute-ways__title {
  margin: 0;
  font-family: var(--openms-font-heading);
  font-size: var(--openms-section-title-size) !important;
  font-weight: var(--openms-heading-lg-weight, 800);
  line-height: 1.15;
  letter-spacing: -0.02em;
  text-transform: uppercase;
  color: var(--openms-navy);
}

.contribute-ways__lead {
  margin: var(--pro-stack-lead, 1rem) 0 0;
  max-width: 42ch;
  font-size: var(--openms-body-size-lg);
  line-height: 1.65;
  color: var(--openms-text-muted) !important;
  text-wrap: pretty;
}

/* Asymmetric side-by-side cards */
.contribute-track {
  display: grid;
  grid-template-columns: repeat(12, minmax(0, 1fr));
  gap: var(--pro-card-gap, clamp(1rem, 2vw, 1.5rem));
  margin: 0;
  padding: 0 var(--contribute-gutter) 0;
  list-style: none;
  box-sizing: border-box;
  align-items: stretch;
}

.contribute-track__item {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  grid-template-rows: auto 1fr;
  align-content: stretch;
  align-items: stretch;
  justify-items: start;
  gap: var(--contribute-space-2, 0.75rem);
  min-width: 0;
  height: 100%;
  min-height: 100%;
  padding: var(--pro-card-pad-lg, clamp(1.25rem, 2.5vw, 1.75rem));
  border: 1px solid var(--contribute-border);
  border-radius: var(--pro-radius, 1rem);
  background: var(--openms-white);
  box-sizing: border-box;
  color: var(--openms-navy);
  transition:
    border-color var(--contribute-motion),
    box-shadow var(--contribute-motion),
    background-color var(--contribute-motion),
    color var(--contribute-motion),
    transform var(--contribute-motion);
}

.contribute-track__body {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  align-self: stretch;
  flex: 1 1 auto;
  gap: 0.4rem;
  min-width: 0;
  width: 100%;
  height: 100%;
  min-height: 0;
}

/* Soft blue icons — above title/body */
.contribute-track__icon {
  display: grid;
  place-items: center;
  width: auto;
  height: auto;
  margin: 0;
  padding: 0;
  border: none;
  border-radius: 0;
  background: transparent;
  color: rgba(var(--openms-blue-rgb), 0.28);
  font-size: var(--pro-card-icon-size, clamp(2.5rem, 4.2vw, 3.15rem));
  line-height: 1;
  transition: color var(--contribute-motion);
}

.contribute-track__icon .fab,
.contribute-track__icon .fas,
.contribute-track__icon .svg-inline--fa {
  color: inherit !important;
  font-size: 1em;
  width: 1em;
  height: 1em;
}

.contribute-track__icon .svg-inline--fa path {
  fill: currentColor !important;
}

.contribute-track__item:hover .contribute-track__icon,
.contribute-track__item:focus-within .contribute-track__icon {
  color: rgba(var(--openms-white-rgb), 0.88);
}

.contribute-track__item:hover,
.contribute-track__item:focus-within {
  border-color: transparent;
  background: var(--openms-navy);
  color: var(--openms-white);
  box-shadow: var(--pro-shadow-hover, 0 0.65rem 1.5rem rgba(var(--openms-navy-rgb), 0.1));
  transform: translateY(-2px);
}

.contribute-track__item:hover .contribute-track__title,
.contribute-track__item:focus-within .contribute-track__title {
  color: var(--openms-white);
}

.contribute-track__item:hover .contribute-track__text,
.contribute-track__item:focus-within .contribute-track__text {
  color: rgba(var(--openms-white-rgb), 0.78);
}

.contribute-track__item:hover .contribute-track__cta,
.contribute-track__item:focus-within .contribute-track__cta {
  color: var(--openms-white) !important;
}

.openms-lib-page--contribute .contribute-track__item:hover .contribute-project-link,
.openms-lib-page--contribute .contribute-track__item:focus-within .contribute-project-link {
  border-color: rgba(var(--openms-white-rgb), 0.28);
  color: var(--openms-white) !important;
  background: rgba(var(--openms-white-rgb), 0.08);
}

.openms-lib-page--contribute .contribute-track__item:hover .contribute-project-links,
.openms-lib-page--contribute .contribute-track__item:focus-within .contribute-project-links {
  border-top-color: rgba(var(--openms-white-rgb), 0.18);
}

.openms-lib-page--contribute .contribute-track__item:hover .contribute-project-link:hover,
.openms-lib-page--contribute .contribute-track__item:hover .contribute-project-link:focus-visible,
.openms-lib-page--contribute .contribute-track__item:focus-within .contribute-project-link:hover,
.openms-lib-page--contribute .contribute-track__item:focus-within .contribute-project-link:focus-visible {
  border-color: rgba(var(--openms-white-rgb), 0.5);
  background: rgba(var(--openms-white-rgb), 0.14);
  color: var(--openms-white) !important;
}

.openms-lib-page--contribute .contribute-track__item:hover .contribute-os-buttons .openms-lib-btn--ghost,
.openms-lib-page--contribute .contribute-track__item:focus-within .contribute-os-buttons .openms-lib-btn--ghost {
  border-color: rgba(var(--openms-white-rgb), 0.92) !important;
  color: var(--openms-white) !important;
  background: transparent !important;
}

.openms-lib-page--contribute .contribute-track__item:hover .contribute-os-buttons .openms-lib-btn--ghost:hover,
.openms-lib-page--contribute .contribute-track__item:hover .contribute-os-buttons .openms-lib-btn--ghost:focus-visible,
.openms-lib-page--contribute .contribute-track__item:focus-within .contribute-os-buttons .openms-lib-btn--ghost:hover,
.openms-lib-page--contribute .contribute-track__item:focus-within .contribute-os-buttons .openms-lib-btn--ghost:focus-visible {
  border-color: var(--openms-white) !important;
  color: var(--openms-white) !important;
  background: rgba(var(--openms-white-rgb), 0.12) !important;
  box-shadow: 0 0 0 var(--openms-btn-glow-size, 6px) rgba(var(--openms-white-rgb), 0.22) !important;
}

.openms-lib-page--contribute .contribute-track__item:hover .contribute-os-buttons .openms-lib-btn--ghost .fab,
.openms-lib-page--contribute .contribute-track__item:hover .contribute-os-buttons .openms-lib-btn--ghost .svg-inline--fa,
.openms-lib-page--contribute .contribute-track__item:hover .contribute-os-buttons .openms-lib-btn--ghost .openms-lib-btn__label,
.openms-lib-page--contribute .contribute-track__item:focus-within .contribute-os-buttons .openms-lib-btn--ghost .fab,
.openms-lib-page--contribute .contribute-track__item:focus-within .contribute-os-buttons .openms-lib-btn--ghost .svg-inline--fa,
.openms-lib-page--contribute .contribute-track__item:focus-within .contribute-os-buttons .openms-lib-btn--ghost .openms-lib-btn__label {
  color: var(--openms-white) !important;
}

.openms-lib-page--contribute .contribute-track__item:hover .contribute-os-buttons .openms-lib-btn--ghost .svg-inline--fa path,
.openms-lib-page--contribute .contribute-track__item:focus-within .contribute-os-buttons .openms-lib-btn--ghost .svg-inline--fa path {
  fill: currentColor !important;
}

.contribute-track__item--wide {
  grid-column: span 7;
}

.contribute-track__item--mid {
  grid-column: span 5;
}

.contribute-track__item--docs {
  grid-column: span 4;
}

.contribute-track__item--design {
  grid-column: span 4;
}

.contribute-track__item--web {
  grid-column: span 4;
}

.contribute-track__title {
  margin: 0;
  font-family: var(--openms-font-heading);
  font-size: var(--openms-card-title-size) !important;
  font-weight: 700;
  line-height: 1.3;
  letter-spacing: -0.01em;
  text-transform: none;
  color: var(--openms-navy);
}

.contribute-track__item--wide .contribute-track__title,
.contribute-track__item--mid .contribute-track__title {
  font-size: var(--openms-secondary-heading-size-lg) !important;
  font-weight: 800;
  letter-spacing: -0.02em;
  text-transform: none;
}

.contribute-track__text {
  margin: 0;
  max-width: none;
  font-size: var(--openms-body-size);
  line-height: 1.6;
  color: rgba(var(--openms-navy-rgb), 0.68);
}

.contribute-track__cta {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  width: fit-content;
  margin-top: auto;
  padding-top: 0.85rem;
  font-size: var(--openms-text-min);
  font-weight: 700;
  color: var(--openms-navy);
  text-decoration: none !important;
  transition: gap var(--contribute-motion), color var(--contribute-motion);
}

.contribute-track__item--design .contribute-track__body,
.contribute-track__item--web .contribute-track__body,
.contribute-track__item--docs .contribute-track__body {
  gap: 0.35rem;
}

.contribute-track__cta:hover,
.contribute-track__cta:focus-visible {
  gap: 0.55rem;
  color: var(--openms-blue) !important;
  outline: none;
}

.openms-lib-page--contribute .contribute-project-links {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: var(--contribute-space-2);
  margin-top: auto;
  margin-bottom: 0;
  padding: var(--contribute-space-3) 0 0;
  list-style: none;
  width: 100%;
  max-width: none;
  align-self: stretch;
  border-top: 1px solid var(--contribute-border);
}

.openms-lib-page--contribute .contribute-project-links li {
  min-width: 0;
}

.openms-lib-page--contribute .contribute-project-link {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 100%;
  box-sizing: border-box;
  min-height: 2.75rem;
  padding: 0.55rem 0.75rem;
  border: 1px solid var(--contribute-border);
  border-radius: var(--openms-btn-pill-radius, 999px);
  background: transparent;
  font-size: var(--openms-text-min);
  font-weight: 700;
  color: var(--openms-navy) !important;
  text-decoration: none !important;
  text-align: center;
  line-height: 1.2;
  transition:
    color var(--contribute-motion),
    border-color var(--contribute-motion),
    background-color var(--contribute-motion),
    transform var(--contribute-motion);
}

.openms-lib-page--contribute .contribute-project-link:hover,
.openms-lib-page--contribute .contribute-project-link:focus-visible {
  border-color: rgba(var(--openms-blue-rgb), 0.4);
  color: var(--openms-blue) !important;
  background: rgba(var(--openms-blue-rgb), 0.04);
  transform: translateY(-1px);
  outline: none;
}

.openms-lib-page--contribute .contribute-project-link__name {
  color: inherit;
  letter-spacing: 0.01em;
  margin: 0;
}

.openms-lib-page--contribute .contribute-os-buttons {
  display: flex;
  flex-direction: row;
  flex-wrap: wrap;
  gap: var(--contribute-space-2);
  justify-content: flex-start;
  margin-top: auto;
  padding-top: var(--contribute-space-3);
  align-self: stretch;
}

.openms-lib-page--contribute .contribute-os-buttons .openms-lib-btn,
.openms-lib-page--contribute .contribute-os-buttons .openms-lib-btn--ghost {
  min-width: 0;
  flex: 1 1 auto;
  justify-content: center;
  border-color: var(--openms-blue) !important;
  background: var(--openms-blue) !important;
  color: var(--openms-white) !important;
  box-shadow: none !important;
}

.openms-lib-page--contribute .contribute-os-buttons .openms-lib-btn:hover,
.openms-lib-page--contribute .contribute-os-buttons .openms-lib-btn:focus-visible,
.openms-lib-page--contribute .contribute-os-buttons .openms-lib-btn--ghost:hover,
.openms-lib-page--contribute .contribute-os-buttons .openms-lib-btn--ghost:focus-visible {
  border-color: var(--openms-blue) !important;
  background: color-mix(in srgb, var(--openms-blue) 88%, var(--openms-navy)) !important;
  color: var(--openms-white) !important;
  transform: none;
  box-shadow: 0 0 0 var(--openms-btn-glow-size, 6px) rgba(var(--openms-blue-rgb), 0.28) !important;
  outline: none;
}

.openms-lib-page--contribute .contribute-os-buttons .openms-lib-btn .fab,
.openms-lib-page--contribute .contribute-os-buttons .openms-lib-btn .svg-inline--fa,
.openms-lib-page--contribute .contribute-os-buttons .openms-lib-btn--ghost .fab,
.openms-lib-page--contribute .contribute-os-buttons .openms-lib-btn--ghost .svg-inline--fa {
  color: var(--openms-white) !important;
}

.openms-lib-page--contribute .contribute-os-buttons .openms-lib-btn .svg-inline--fa path,
.openms-lib-page--contribute .contribute-os-buttons .openms-lib-btn--ghost .svg-inline--fa path {
  fill: currentColor !important;
}

/* ═══════════════════════════════════════════
   7. SUPPORT — horizontal CTA band
   ═══════════════════════════════════════════ */
.contribute-support {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: start;
  row-gap: 0.4rem;
  column-gap: clamp(1.5rem, 4vw, 3rem);
  width: 100%;
  margin: 0;
  padding: clamp(1.75rem, 3.5vw, 2.5rem) var(--contribute-gutter);
  box-sizing: border-box;
  border: none;
  border-radius: 0;
  background:
    linear-gradient(
      135deg,
      color-mix(in srgb, var(--openms-blue) 7%, var(--openms-white)) 0%,
      color-mix(in srgb, var(--olib-bg-soft, #f4f6f9) 80%, var(--openms-white)) 100%
    );
  color: var(--openms-navy);
  text-decoration: none !important;
}

.contribute-support__copy {
  display: contents;
}

.contribute-support__kicker {
  grid-column: 1;
  margin: 0;
  font-size: var(--openms-text-min);
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--openms-blue);
}

.contribute-support__title {
  grid-column: 1;
  margin: 0;
  font-family: var(--openms-font-heading);
  font-size: var(--openms-secondary-heading-size-lg) !important;
  font-weight: 800;
  line-height: 1.2;
  letter-spacing: -0.02em;
  text-transform: none;
  color: var(--openms-navy) !important;
}

.contribute-support__text {
  grid-column: 1;
  align-self: center;
  margin: 0;
  max-width: 42ch;
  font-size: var(--openms-body-size);
  line-height: 1.55;
  color: var(--openms-text-muted) !important;
}

.contribute-support__cta {
  grid-column: 2;
  grid-row: 3;
  justify-self: end;
  align-self: center;
  white-space: nowrap;
}

/* ═══════════════════════════════════════════
   8. OUTREACH — copy + vertical social rail
   ═══════════════════════════════════════════ */
.contribute-outreach {
  padding: var(--pro-head-to-content, var(--contribute-space-6)) var(--contribute-gutter) 0;
  background: transparent;
}

.contribute-outreach__inner {
  display: grid;
  grid-template-columns: minmax(0, 1.15fr) minmax(16rem, 0.85fr);
  gap: var(--contribute-space-5) var(--pro-col-gap, clamp(2rem, 6vw, 5rem));
  align-items: center;
  width: 100%;
  margin-inline: 0;
}

.contribute-outreach__copy {
  display: grid;
  gap: var(--contribute-space-2);
  max-width: 40rem;
}

.contribute-outreach__title {
  margin: 0;
  font-family: var(--openms-font-heading);
  font-size: var(--openms-section-title-size) !important;
  font-weight: 800;
  line-height: 1.15;
  letter-spacing: -0.02em;
  text-transform: uppercase;
  color: var(--openms-navy);
}

.contribute-outreach__text,
.contribute-outreach__contact {
  margin: 0;
  font-size: var(--openms-body-size-lg);
  line-height: 1.65;
  color: var(--openms-text-muted) !important;
}

.contribute-outreach__contact a {
  font-weight: 700;
  color: var(--openms-content-link, var(--openms-navy)) !important;
  text-decoration: none !important;
}

.contribute-outreach__contact a:hover,
.contribute-outreach__contact a:focus-visible {
  text-decoration: none !important;
}

.contribute-outreach__social {
  display: grid;
  gap: 0;
  margin: 0;
  padding: 0;
  list-style: none;
  border-top: 1px solid var(--contribute-border);
}

.contribute-outreach__social > li {
  border-bottom: 1px solid var(--contribute-border);
}

.contribute-outreach__social-link {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  gap: var(--contribute-space-2) var(--contribute-space-3);
  align-items: center;
  width: 100%;
  min-height: 4.25rem;
  padding: 0.85rem 0.15rem 0.85rem 0;
  border: none;
  border-radius: 0;
  background: transparent;
  color: var(--openms-navy) !important;
  text-decoration: none !important;
  transition:
    color var(--contribute-motion),
    background-color var(--contribute-motion),
    padding-left var(--contribute-motion);
}

.contribute-outreach__social-link:hover,
.contribute-outreach__social-link:focus-visible {
  color: var(--openms-blue) !important;
  background: transparent;
  padding-left: 0.35rem;
  outline: none;
}

.contribute-outreach__social-icon {
  display: grid;
  place-items: center;
  width: 2.25rem;
  height: 2.25rem;
  font-size: 1.05rem;
  color: inherit;
}

.contribute-outreach__social-meta {
  display: grid;
  gap: 0.15rem;
  min-width: 0;
}

.contribute-outreach__social-label {
  font-size: var(--openms-body-size);
  font-weight: 700;
  letter-spacing: 0.02em;
  line-height: 1.2;
}

.contribute-outreach__social-hint {
  font-size: var(--openms-text-min);
  font-weight: 500;
  letter-spacing: 0;
  text-transform: none;
  color: rgba(var(--openms-navy-rgb), 0.5);
  transition: color var(--contribute-motion);
}

.contribute-outreach__social-link:hover .contribute-outreach__social-hint,
.contribute-outreach__social-link:focus-visible .contribute-outreach__social-hint {
  color: rgba(var(--openms-blue-rgb), 0.7);
}

.contribute-outreach__social-arrow {
  font-size: var(--openms-text-min);
  font-weight: 700;
  opacity: 0.35;
  transition:
    opacity var(--contribute-motion),
    transform var(--contribute-motion);
}

.contribute-outreach__social-link:hover .contribute-outreach__social-arrow,
.contribute-outreach__social-link:focus-visible .contribute-outreach__social-arrow {
  opacity: 1;
  transform: translateX(0.25rem);
}

/* ── CoC outro — full-bleed shell; panel fills content column ── */
.openms-lib-page--contribute #code-of-conduct.openms-lib-page__anchor {
  background: var(--openms-white);
  padding-inline: var(--contribute-gutter);
  padding-block: var(--contribute-section-y);
}

.openms-lib-page--contribute .contribute-coc-band {
  width: 100%;
  max-width: none;
  margin-inline: 0;
}

/* ── Responsive ── */
@media (max-width: 960px) {
  .contribute-channels__strip {
    grid-template-columns: 1fr;
  }

  .contribute-channel {
    border-right: none;
    border-bottom: 1px solid var(--contribute-border);
    padding-inline: 0;
  }

  .contribute-channel:last-child {
    border-bottom: none;
  }

  .contribute-channels__head {
    text-align: left;
    justify-items: start;
    max-width: none;
  }

  .openms-lib-page--contribute .contribute-project-links {
    grid-template-columns: repeat(4, minmax(0, 1fr));
  }

  .contribute-track {
    grid-template-columns: 1fr 1fr;
  }

  .contribute-track__item--wide,
  .contribute-track__item--mid,
  .contribute-track__item--docs,
  .contribute-track__item--design,
  .contribute-track__item--web {
    grid-column: span 1;
  }

  .contribute-track__item--wide {
    grid-column: 1 / -1;
  }

  .contribute-support {
    grid-template-columns: 1fr;
    justify-items: start;
    gap: 1.25rem;
  }

  .contribute-support__copy {
    display: grid;
    gap: 0.4rem;
    justify-items: start;
    text-align: left;
  }

  .contribute-support__cta {
    grid-column: 1;
    grid-row: auto;
    justify-self: start;
  }

  .contribute-outreach__inner {
    grid-template-columns: 1fr;
    justify-items: stretch;
  }

  .contribute-outreach__copy {
    max-width: none;
    width: 100%;
  }

  .contribute-outreach__social,
  .contribute-outreach__social > li,
  .contribute-outreach__social-link {
    width: 100%;
    max-width: none;
  }
}

@media (max-width: 720px) {
  /* One shared content column: section owns the gutter; children fill it */
  .openms-lib-page--contribute .contribute-ways {
    padding-inline: var(--contribute-gutter);
    box-sizing: border-box;
    width: 100%;
  }

  .openms-lib-page--contribute .contribute-ways__head,
  .openms-lib-page--contribute .contribute-track,
  .openms-lib-page--contribute .contribute-support,
  .openms-lib-page--contribute .contribute-outreach {
    padding-inline: 0 !important;
    width: 100% !important;
    max-width: 100% !important;
    box-sizing: border-box;
  }

  .openms-lib-page--contribute .contribute-channels__strip,
  .openms-lib-page--contribute .contribute-channel,
  .openms-lib-page--contribute .contribute-track,
  .openms-lib-page--contribute .contribute-track__item,
  .openms-lib-page--contribute .contribute-support,
  .openms-lib-page--contribute .contribute-outreach__inner,
  .openms-lib-page--contribute .contribute-outreach__social,
  .openms-lib-page--contribute .contribute-outreach__social > li,
  .openms-lib-page--contribute .contribute-outreach__social-link,
  .openms-lib-page--contribute .contribute-coc-band,
  .openms-lib-page--contribute .contribute-coc-band__panel {
    width: 100% !important;
    max-width: 100% !important;
    box-sizing: border-box;
  }

  .openms-lib-page--contribute .contribute-ways__lead,
  .openms-lib-page--contribute .contribute-support__copy,
