/* ===== zz-page-shell.css ===== */
/* Shared page shell — one content width across the site.
   Loads late (zz-*) so page-specific narrower max-widths lose.
   Pattern: full-bleed section uses --openms-page-inline gutters;
   content rails use max-width: var(--pro-max) with no extra side pad. */

.openms-lib-page,
.home-page,
[class$="-page-layout"],
.community-calendar-layout {
  /* Re-declare so gutters always track the live --pro-max */
  --openms-page-inline: max(
    var(--olib-pad-x),
    calc((100% - var(--pro-max)) / 2)
  );
  --pro-hero-content-max: min(100%, var(--pro-max));
  --pro-cluster-max: min(100%, var(--pro-max));
  --hub-wide-max: var(--pro-max);
}

@media (max-width: 720px) {
  .openms-lib-page,
  .home-page,
  [class$="-page-layout"],
  .community-calendar-layout {
    --openms-page-inline: var(--openms-page-gutter);
  }
}

