/* ===== zzzz-mobile-gutters.css ===== */
/* Tighter side gutters on phones so components use more of the screen.
   Two things were shrinking content at 375px:
     1. the shared gutter token resolved to 1.35rem (21.6px) per side, and
     2. homepage sections nest a padded wrapper inside an already-padded block,
        doubling that to ~43px per side (cards were 289px of a 375px screen).
   Filename sorts last; !important is needed to beat page-scoped selectors. */

@media (max-width: 720px) {
  :root,
  .openms-lib-page,
  .home-page,
  [class$="-page-layout"],
  .community-calendar-layout {
    --openms-page-gutter: max(0.9rem, env(safe-area-inset-left, 0px), env(safe-area-inset-right, 0px));
    --olib-pad-x: var(--openms-page-gutter);
    --pro-pad: var(--openms-page-gutter);
    --home-pad-x: var(--openms-page-gutter);
    --openms-page-inline: var(--openms-page-gutter);
    /* Navbar runs tighter than the content gutter — logo and burger sit close
       to the screen edges, with tap padding coming from the controls instead */
    --openms-navbar-container-pad-inline-mobile: 0.5rem;
  }

  /* Section wrappers inside an already-padded homepage block. Descendant, not
     child: some blocks wrap the section in an extra unpadded div. */
  .home-page__block .webapps-featured,
  .home-page__block .webapps-affiliates,
  .home-page__block .webapps-archived,
  .home-page__block .home-metrics,
  .home-page__block .uni-partners,
  .home-page__block .keyfeatures-modern,
  .home-page__block .ecosystem-home,
  .home-page__block .community-home,
  .home-page__block .community-news-events,
  .home-page__block .community-events-home,
  .home-page__block .contact-home,
  .home-page__block .contact-area,
  .home-page__block .hero-sponsors,
  .home-page__block .trusted-by,
  .home-page__block .home-page__container {
    padding-inline: 0 !important;
    max-width: 100% !important;
  }

  /* ...and their inner rails, which add the gutter a second time */
  .home-page__block .webapps-featured__inner,
  .home-page__block .webapps-affiliates__inner,
  .home-page__block .webapps-archived__inner,
  .home-page__block .home-metrics__inner,
  .home-page__block .uni-partners__inner,
  .home-page__block .keyfeatures-modern__inner,
  .home-page__block .ecosystem-home__inner,
  .home-page__block .community-home__inner,
  .home-page__block .community-news-events__inner,
  .home-page__block .community-events-home__inner,
  .home-page__block .contact-home__inner,
  .home-page__block .contact-area__inner,
  .home-page__block .hero-sponsors__inner,
  .home-page__block .trusted-by__inner,
  .home-page__block .home-section-head {
    padding-inline: 0 !important;
    width: 100% !important;
    max-width: 100% !important;
    margin-inline: 0 !important;
  }

  /* Inner-page sections do the same nesting inside .openms-lib-block */
  .openms-lib-page .openms-lib-block > .openms-lib-block__inner,
  .openms-lib-page .webapps-featured__inner,
  .openms-lib-page .webapps-affiliates__inner,
  .openms-lib-page .webapps-archived__inner,
  .openms-lib-page .uni-partners__inner,
  [class$="-page-layout"] .uni-partners__inner,
  /* Calendar / News: block sits inside an already-padded anchor (no __inner) */
  .openms-lib-page--calendar .openms-lib-page__body > .openms-lib-page__anchor > .openms-lib-block,
  .openms-lib-page--calendar .community-calendar-block,
  .openms-lib-page--news .openms-lib-page__body > .openms-lib-page__anchor > .openms-lib-block,
  .openms-lib-page--news .news-page-block {
    padding-inline: 0 !important;
    max-width: 100% !important;
    width: 100% !important;
  }

  /* Card interiors: trim the inset so text gets the width back.
     Catalog Featured Apps cards keep padding:0 — the white surface is the
     full-bleed shell; media/content already own their own insets.
     Do not pad .community-events-home__card — it's only a list wrapper; the
     visible surface is .community-events-home__card-link (already padded). */
  .about-sponsor-card,
  .contact-home__card,
  .contact-page__support-card,
  .contribute-channel,
  .contribute-way,
  .coc-principle,
  .developer-retreat-highlights__card,
  .donate-impact-card,
  .ecosystem-home__card,
  .events-past-card,
  .fellowship-project-card,
  .governance-card,
  .home-metrics__card,
  .keyfeatures-modern__topic-card,
  .leadership-card,
  .openms-lib-about__benefit,
  .openms-lib-about__tile,
  .openms-lib-developers__card,
  .openms-lib-resource-card,
  .openms-lib-resources__explore-card,
  .openms-lib-topp-split__card,
  .privacy-overview__item,
  .publications-cite-card,
  .sponsor-tier,
  .sponsor-why__card,
  .webapps-project-card:not(.webapps-project-card--catalog),
  .webapps-project-detail-card,
  .webapps-archived-entry {
    padding-inline: clamp(0.85rem, 3.4vw, 1.1rem) !important;
  }

  /* Calendar / events / news: wrappers must stay full-bleed so cards match titles */
  .community-events-home__card,
  .news-home__card,
  .openms-lib-page--calendar .community-events-home__card,
  .community-calendar-layout .community-events-home__card,
  .openms-lib-page--news .community-events-home__card,
  .openms-lib-page--news .news-home__card {
    padding-inline: 0 !important;
    width: 100% !important;
